func TestParseDateIgnoresLocalTimeZone(t *testing.T) {
	// A zone well east of UTC would shift the calendar day if the parse were
	// local-relative.
	kiribati := time.FixedZone("LINT", 14*60*60)
	orig := time.Local
	time.Local = kiribati
	t.Cleanup(func() { time.Local = orig })

	got, err := parseDate("2024-03-15")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	want := time.Date(2024, time.March, 15, 0, 0, 0, 0, time.UTC)
	if !got.Equal(want) || got.Location() != time.UTC {
		t.Errorf("parseDate(\"2024-03-15\") = %v (%v), want %v (UTC)", got, got.Location(), want)
